<?php require dirname(__DIR__).'/bootstrap.php';$u=uid();admin();$error='';$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=(string)($_POST['action']??'');try{if($a==='settings'){foreach(['session_minutes'=>[5,43200],'code_minutes'=>[2,30],'max_import_mb'=>[1,1000]] as $key=>$bounds){$value=max($bounds[0],min($bounds[1],(int)($_POST[$key]??$bounds[0])));q('INSERT INTO mn_settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$key,(string)$value]);}$notice='Settings saved.';}if($a==='add_user'){$email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Invalid email');q('INSERT INTO mn_users(email,enabled,is_admin) VALUES(?,1,0) ON DUPLICATE KEY UPDATE enabled=1',[$email]);$notice='Email allowed.';}if($a==='disable_user'){$id=(int)($_POST['user_id']??0);if($id===$u)throw new RuntimeException('Cannot disable your own account');q('UPDATE mn_users SET enabled=0 WHERE id=?',[$id]);$notice='Email disabled.';}if($a==='change_email'){$email=strtolower(trim((string)($_POST['new_email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Invalid email');q('UPDATE mn_users SET email=? WHERE id=?',[$email,$u]);$notice='Your email updated. Future codes go to the new address.';}}catch(Throwable $e){$error=$e->getMessage();}}$users=q('SELECT id,email,enabled,is_admin FROM mn_users ORDER BY email')->fetchAll();?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MyNotes · Admin</title><link rel="stylesheet" href="../style.css"><header><a class="brand" href="../index.php">My<span>Notes</span></a><a href="../index.php">Back to notes</a></header><main><section class="panel"><h1>Administration</h1><?php if($notice):?><p class="notice"><?=h($notice)?></p><?php endif;?><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><h2>Settings</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="settings"><label>Session inactivity timeout (minutes)</label><input type="number" name="session_minutes" min="5" max="43200" value="<?=h(setting('session_minutes','10080'))?>"><label>Email code expiration (minutes)</label><input type="number" name="code_minutes" min="2" max="30" value="<?=h(setting('code_minutes','10'))?>"><label>Maximum ZIP import (MB)</label><input type="number" name="max_import_mb" min="1" max="1000" value="<?=h(setting('max_import_mb','100'))?>"><button>Save settings</button></form><h2>Allowed emails</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="add_user"><label>Allow new email</label><input type="email" name="email" required><button>Allow email</button></form><?php foreach($users as $person):?><div class="note"><strong><?=h($person['email'])?></strong> <?= $person['is_admin']?'(admin)':'' ?> <?= $person['enabled']?'':'(disabled)'?><?php if($person['enabled']&&(int)$person['id']!==$u):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="disable_user"><input type="hidden" name="user_id" value="<?=$person['id']?>"><button>Disable access</button></form><?php endif;?></div><?php endforeach;?><h2>Change my email</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="change_email"><input type="email" name="new_email" required><button>Change email</button></form></section></main></html>
